package randomeventhelper.randomevents.gravedigger;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;
import randomeventhelper.RandomEventHelperConfig;

@Slf4j
@Singleton
public class GravediggerItemOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final RandomEventHelperConfig config;
	private final GravediggerHelper gravediggerHelper;

	private final double SCALE_FACTOR = 0.8;

	@Inject
	public GravediggerItemOverlay(Client client, RandomEventHelperConfig config, GravediggerHelper gravediggerHelper)
	{
		this.client = client;
		this.config = config;
		this.gravediggerHelper = gravediggerHelper;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (gravediggerHelper.getCoffinsInInventory() != null && !gravediggerHelper.getCoffinsInInventory().isEmpty() && gravediggerHelper.getCoffinsInInventory().contains(itemId))
		{
			Coffin coffin = Coffin.getCoffinFromItemID(itemId);
			if (config.gravediggerHighlightMode().contains(GravediggerHighlightMode.HIGHLIGHT_COFFIN))
			{
				renderHighlightCoffinInInventory(graphics, widgetItem, coffin);
			}

			if (config.gravediggerHighlightMode().contains(GravediggerHighlightMode.COFFIN_ICON))
			{
				renderCoffinIconInInventory(graphics, widgetItem, coffin);
			}

			if (config.gravediggerHighlightMode().contains(GravediggerHighlightMode.TEXT_COFFIN))
			{
				renderCoffinTextInInventory(graphics, widgetItem, coffin);
			}
		}
	}

	private void renderCoffinTextInInventory(Graphics2D graphics, WidgetItem widgetItem, Coffin coffin)
	{
		Point textPoint = new Point(widgetItem.getCanvasBounds().x - 1, (widgetItem.getCanvasBounds().y - 1) + widgetItem.getCanvasBounds().height);
		String coffinText = this.config.gravediggerUseSkillIcons() ? coffin.getAssociatedSkillName() : coffin.getAssociatedItemName();
		OverlayUtil.renderTextLocation(graphics, textPoint, coffinText, Color.WHITE);
	}

	private void renderCoffinIconInInventory(Graphics2D graphics, WidgetItem widgetItem, Coffin coffin)
	{
		BufferedImage coffinImage = this.config.gravediggerUseSkillIcons() ? this.gravediggerHelper.getCoffinSkillImageMap().get(coffin) : this.gravediggerHelper.getCoffinItemImageMap().get(coffin);
		if (coffinImage == null)
		{
			return;
		}

		BufferedImage rescaledCoffinImage = ImageUtil.resizeImage(coffinImage, (int) (coffinImage.getWidth() * this.SCALE_FACTOR), (int) (coffinImage.getHeight() * this.SCALE_FACTOR));
		Point point = widgetItem.getCanvasLocation();
		// Move the point to be the bottom right of the item
		int dx = (int) (point.getX() + widgetItem.getCanvasBounds().getWidth() - rescaledCoffinImage.getWidth());
		int dy = (int) (point.getY() + 1);
		// Move the point to be at the bottom right, but making sure the x and y are capped within the widget bounds using Math.min
		// dx = Math.min(dx, (int) (widgetItem.getCanvasBounds().getX() + widgetItem.getCanvasBounds().getWidth() - rescaledCoffinImage.getWidth()));
		// dy = Math.min(dy, (int) (widgetItem.getCanvasBounds().getY() + widgetItem.getCanvasBounds().getHeight() - rescaledCoffinImage.getHeight()));
		point = new Point(dx, dy);
		OverlayUtil.renderImageLocation(graphics, point, rescaledCoffinImage);
	}

	private void renderHighlightCoffinInInventory(Graphics2D graphics, WidgetItem widgetItem, Coffin coffin)
	{
		Color requiredCoffinColor = coffin != null ? coffin.getColor() : Color.BLACK;
		Color requiredCoffinTransparentColor = coffin != null ? this.getTransparentColor(coffin.getColor(), 50) : Color.BLACK;
		OverlayUtil.renderPolygon(graphics, widgetItem.getCanvasBounds(), requiredCoffinColor, requiredCoffinTransparentColor, new BasicStroke(2));
	}

	private Color getTransparentColor(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}
}

package randomeventhelper.randomevents.gravedigger;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import randomeventhelper.RandomEventHelperConfig;

@Slf4j
@Singleton
public class GravediggerOverlay extends Overlay
{
	private final Client client;
	private final RandomEventHelperConfig config;
	private final GravediggerHelper gravediggerHelper;
	private final SpriteManager spriteManager;
	private BufferedImage checkBufferedImage;
	private BufferedImage crossBufferedImage;

	@Inject
	public GravediggerOverlay(Client client, RandomEventHelperConfig config, GravediggerHelper gravediggerHelper, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.spriteManager = spriteManager;
		this.gravediggerHelper = gravediggerHelper;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics2D)
	{
		if (this.gravediggerHelper.getGraveMap() != null && !this.gravediggerHelper.getGraveMap().isEmpty())
		{
			if (checkBufferedImage == null)
			{
				this.checkBufferedImage = this.spriteManager.getSprite(SpriteID.OptionsRadioButtons.CHECK_GREEN, 0);
			}
			if (crossBufferedImage == null)
			{
				this.crossBufferedImage = this.spriteManager.getSprite(SpriteID.OptionsRadioButtons.CROSS_RED, 0);
			}
			for (Map.Entry<GraveNumber, Grave> graveEntry : this.gravediggerHelper.getGraveMap().entrySet())
			{
				GraveNumber graveNumber = graveEntry.getKey();
				Grave grave = graveEntry.getValue();
				if (grave != null)
				{
					BufferedImage coffinImage = this.config.gravediggerUseSkillIcons() ? this.gravediggerHelper.getCoffinSkillImageMap().get(grave.getRequiredCoffin()) : this.gravediggerHelper.getCoffinItemImageMap().get(grave.getRequiredCoffin());
					Coffin requiredCoffin = grave.getRequiredCoffin();
					Coffin placedCoffin = grave.getPlacedCoffin();
					if (requiredCoffin == null || placedCoffin == null)
					{
						continue;
					}

					Color requiredCoffinColor = requiredCoffin.getColor();
					Color requiredCoffinTransparentColor = this.getTransparentColor(requiredCoffin.getColor(), 50);
					Color placedCoffinColor = placedCoffin.getColor();
					Color placedCoffinTransparentColor = this.getTransparentColor(placedCoffin.getColor(), 50);

					// Renders the check or cross above the grave depending on if the correct coffin is placed
					GameObject graveObject = grave.getFilledGrave() != null ? grave.getFilledGrave() : grave.getEmptyGrave();
					if (graveObject == null)
					{
						continue;
					}

					Point centeredSpritePoint = Perspective.getCanvasImageLocation(client, graveObject.getLocalLocation(), checkBufferedImage, 0);
					if (centeredSpritePoint != null)
					{
						if (placedCoffin != requiredCoffin)
						{
							OverlayUtil.renderImageLocation(graphics2D, centeredSpritePoint, crossBufferedImage);
						}
						else
						{
							OverlayUtil.renderImageLocation(graphics2D, centeredSpritePoint, checkBufferedImage);
						}
					}

					if (coffinImage != null && config.gravediggerHighlightMode().contains(GravediggerHighlightMode.GRAVESTONE_ICON))
					{
						renderGravestoneIcon(graphics2D, grave, coffinImage, requiredCoffinColor);
					}

					if (coffinImage != null && config.gravediggerHighlightMode().contains(GravediggerHighlightMode.HIGHLIGHT_GRAVE))
					{
						// Highlight the gravestone/headstone
						renderHighlightGravestone(graphics2D, grave, coffinImage, requiredCoffinColor);

						// Highlight the grave itself based on whether it is filled or empty
						if (placedCoffin == Coffin.EMPTY)
						{
							renderHighlightEmptyGrave(graphics2D, grave, requiredCoffinColor, requiredCoffinTransparentColor, 2);
						}
						else
						{
							renderHighlightFilledGrave(graphics2D, grave, placedCoffinColor, placedCoffinTransparentColor, placedCoffin, requiredCoffin, 2);
						}
					}

					if (config.gravediggerHighlightMode().contains(GravediggerHighlightMode.TEXT_GRAVE))
					{
						renderTextGrave(graphics2D, grave, requiredCoffin);
					}
				}
			}
		}
		return null;
	}

	private void renderGravestoneIcon(Graphics2D graphics2D, Grave grave, BufferedImage coffinImage, Color requiredCoffinColor)
	{
		if (grave.getGraveStone() != null)
		{
			Point location = grave.getGraveStone().getCanvasLocation();
			LocalPoint localPoint = grave.getGraveStone().getLocalLocation();
			if (location != null)
			{
				OverlayUtil.renderImageLocation(client, graphics2D, localPoint, coffinImage, 50);
			}
		}
	}

	private void renderHighlightGravestone(Graphics2D graphics2D, Grave grave, BufferedImage coffinImage, Color requiredCoffinColor)
	{
		if (grave.getGraveStone() != null)
		{
			Shape graveStoneHull = grave.getGraveStone().getConvexHull();
			if (graveStoneHull != null)
			{
				OverlayUtil.renderPolygon(graphics2D, graveStoneHull, requiredCoffinColor);
			}
		}
	}

	private void renderHighlightEmptyGrave(Graphics2D graphics2D, Grave grave, Color requiredCoffinColor, Color requiredCoffinTransparentColor, int strokeWidth)
	{
		if (grave.getEmptyGrave() != null)
		{
			Shape emptyGraveHull = grave.getEmptyGrave().getConvexHull();
			if (emptyGraveHull != null)
			{
				OverlayUtil.renderPolygon(graphics2D, emptyGraveHull, requiredCoffinColor, requiredCoffinTransparentColor, new BasicStroke(strokeWidth));
			}
		}
	}

	private void renderHighlightFilledGrave(Graphics2D graphics2D, Grave grave, Color placedCoffinColor, Color placedCoffinTransparentColor, Coffin placedCoffin, Coffin requiredCoffin, int strokeWidth)
	{
		if (grave.getFilledGrave() != null)
		{
			Shape filledGraveHull = grave.getFilledGrave().getConvexHull();
			if (filledGraveHull != null)
			{
				OverlayUtil.renderPolygon(graphics2D, filledGraveHull, placedCoffinColor, placedCoffinTransparentColor, new BasicStroke(strokeWidth));
			}
		}
	}

	private void renderTextGrave(Graphics2D graphics2D, Grave grave, Coffin requiredCoffin)
	{
		GameObject graveObject = grave.getFilledGrave() != null ? grave.getFilledGrave() : grave.getEmptyGrave();
		if (graveObject != null)
		{
			String graveText = this.config.gravediggerUseSkillIcons() ? requiredCoffin.getAssociatedSkillName() : requiredCoffin.getAssociatedItemName();
			Point textPoint = graveObject.getCanvasTextLocation(graphics2D, graveText, 100);
			OverlayUtil.renderTextLocation(graphics2D, textPoint, graveText, Color.WHITE);
		}
	}

	private Color getTransparentColor(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}
}

package randomeventhelper.randomevents.maze;

import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.OverlayManager;
import randomeventhelper.RandomEventHelperConfig;
import randomeventhelper.RandomEventHelperPlugin;
import randomeventhelper.pluginmodulesystem.PluginModule;

@Slf4j
@Singleton
public class MazeHelper extends PluginModule
{
	@Inject
	private PluginManager pluginManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	private static final String PLUGIN_MESSAGE_SHORTEST_PATH_NAMESPACE = "shortestpath";
	private static final String PLUGIN_MESSAGE_SHORTEST_PATH_PATH_KEY = "path";
	private static final String PLUGIN_MESSAGE_SHORTEST_PATH_CLEAR_KEY = "clear";

	private GameObject mazeExitObject;

	@Inject
	public MazeHelper(OverlayManager overlayManager, RandomEventHelperConfig config, Client client)
	{
		super(overlayManager, config, client);
	}

	@Override
	public void onStartUp()
	{
		this.checkShortestPathPluginStatus();
		this.mazeExitObject = null;
	}

	@Override
	public void onShutdown()
	{
		Optional<Plugin> shortestPathPlugin = pluginManager.getPlugins().stream().filter(plugin -> plugin.getName().equals("Shortest Path")).findAny();
		if (shortestPathPlugin.isPresent())
		{
			if (pluginManager.isPluginEnabled(shortestPathPlugin.get()))
			{
				this.sendShortestPathClear();
			}
		}
		this.mazeExitObject = null;
	}

	@Override
	public boolean isEnabled()
	{
		return this.config.isMazeEnabled();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned gameObjectSpawned)
	{
		if (gameObjectSpawned.getGameObject().getId() == ObjectID.MACRO_MAZE_COMPLETE)
		{
			if (gameObjectSpawned.getGameObject() != null)
			{
				this.mazeExitObject = gameObjectSpawned.getGameObject();
				if (!this.checkShortestPathPluginStatus())
				{
					return;
				}
				LocalPoint shrineLocalPoint = gameObjectSpawned.getGameObject().getLocalLocation();
				WorldPoint instancedShrineWorldPoint = WorldPoint.fromLocalInstance(this.client, shrineLocalPoint);
				log.debug("Detected maze exit object spawn, setting shortest path to it");
				this.sendShortestPathDestination(instancedShrineWorldPoint);
			}
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned gameObjectDespawned)
	{
		if (gameObjectDespawned.getGameObject().getId() == ObjectID.MACRO_MAZE_COMPLETE)
		{
			log.debug("Detected maze exit object despawn, clearing shortest path");
			this.mazeExitObject = null;
			this.sendShortestPathClear();
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged pluginChanged)
	{
		log.debug("[#onPluginChanged] Plugin changed: {} | Loaded: {}", pluginChanged.getPlugin().getName(), pluginChanged.isLoaded());
		if (pluginChanged.getPlugin().getName().equals("Shortest Path") && pluginChanged.isLoaded())
		{
			log.debug("[#onPluginChanged] Shortest Path plugin was loaded, re-sending current maze exit object if it exists");
			if (this.mazeExitObject != null)
			{
				GameObjectSpawned gameObjectSpawned = new GameObjectSpawned();
				gameObjectSpawned.setGameObject(this.mazeExitObject);
				this.clientThread.invokeLater(() -> {
					this.onGameObjectSpawned(gameObjectSpawned);
					log.debug("[#onPluginChanged] Re-sent current maze exit object to Shortest Path plugin after it was enabled");
				});
			}
		}
	}

	private boolean checkShortestPathPluginStatus()
	{
		Optional<Plugin> shortestPathPlugin = pluginManager.getPlugins().stream().filter(plugin -> plugin.getName().equals("Shortest Path")).findAny();

		if (shortestPathPlugin.isPresent())
		{
			if (!pluginManager.isPluginEnabled(shortestPathPlugin.get()))
			{
				log.warn("[#onStartUp] ShortestPathPlugin is not enabled. Please enable it manually to ensure maze helper's functionality.");
				if (this.isLoggedIn())
				{
					String disabledPluginMessage = RandomEventHelperPlugin.getChatMessageBuilderWithPrefix()
						.append("You've enabled the maze helper module but have the Shortest Path plugin disabled. Please enable it manually to ensure functionality.")
						.build();
					RandomEventHelperPlugin.sendChatMessage(this.chatMessageManager, disabledPluginMessage);
					return false;
				}
			}
		}
		else
		{
			log.warn("[#onStartUp] Random Event Helper's Maze Helper requires the Shortest Path plugin found on the Plugin Hub to function properly. Please ensure Shortest Path is installed and enabled for Maze pathing support.");
			if (this.isLoggedIn())
			{
				String notInstalledPluginMessage = RandomEventHelperPlugin.getChatMessageBuilderWithPrefix()
					.append("You've enabled the maze helper module but don't have the Shortest Path plugin installed. Please ensure Shortest Path is installed and enabled for Maze pathing support.")
					.build();
				RandomEventHelperPlugin.sendChatMessage(this.chatMessageManager, notInstalledPluginMessage);
				return false;
			}
		}
		return true;
	}

	private boolean sendShortestPathDestination(WorldPoint destinationWorldPoint)
	{
		if (destinationWorldPoint == null)
		{
			log.warn("[#sendShortestPathDestinations] The destination is null so we can't set a path");
			return false;
		}

		Map<String, Object> payload = this.generatePathPayload(destinationWorldPoint);
		if (payload.isEmpty())
		{
			log.warn("[#sendShortestPathDestinations] Failed to generate payload for path generation");
			return false;
		}

		this.sendShortestPathClear();
		this.eventBus.post(new PluginMessage(PLUGIN_MESSAGE_SHORTEST_PATH_NAMESPACE, PLUGIN_MESSAGE_SHORTEST_PATH_PATH_KEY, payload));
		return true;
	}

	private Map<String, Object> generatePathPayload(WorldPoint destinationWorldPoint)
	{
		LocalPoint startingLocalPoint = client.getLocalPlayer().getLocalLocation();

		if (startingLocalPoint == null)
		{
			log.warn("[#generatePathPayload(WorldPoint)] Player's starting local point is null, cannot generate payload starting point");
			return Map.of();
		}

		WorldPoint localInstanceStartingWorldPoint = WorldPoint.fromLocalInstance(this.client, startingLocalPoint);
		log.debug("[#generatePathPayload(WorldPoint)] Converted player's local point {} to local instance world point {}", startingLocalPoint, localInstanceStartingWorldPoint);
		return this.generatePathPayload(localInstanceStartingWorldPoint, destinationWorldPoint);
	}

	private Map<String, Object> generatePathPayload(WorldPoint startingWorldPoint, WorldPoint destinationWorldPoint)
	{
		log.debug("[#generatePathPayload(WorldPoint, WorldPoint)] Generated path payload with starting point: {} and destination point: {}", startingWorldPoint, destinationWorldPoint);
		return Map.of(
			"start", startingWorldPoint,
			"target", destinationWorldPoint
		);
	}

	private void sendShortestPathClear()
	{
		this.eventBus.post(new PluginMessage(PLUGIN_MESSAGE_SHORTEST_PATH_NAMESPACE, PLUGIN_MESSAGE_SHORTEST_PATH_CLEAR_KEY));
	}

	private boolean isInMazeLocalInstance()
	{
		return RandomEventHelperPlugin.getRegionIDFromCurrentLocalPointInstanced(client) == 11591;
	}
}

